-- Gold Query
SELECT DISTINCT "emp_fname", "emp_dob" FROM (SELECT "class_code", "crs_code", "class_section", "class_time", "class_room", "prof_num", "emp_lname", "emp_fname", "emp_initial", "emp_jobcode", "emp_hiredate", "emp_dob", "prof_num" AS "emp_num" FROM (SELECT "LHS"."class_code" AS "class_code", "LHS"."crs_code" AS "crs_code", "LHS"."class_section" AS "class_section", "LHS"."class_time" AS "class_time", "LHS"."class_room" AS "class_room", "LHS"."prof_num" AS "prof_num", "RHS"."emp_lname" AS "emp_lname", "RHS"."emp_fname" AS "emp_fname", "RHS"."emp_initial" AS "emp_initial", "RHS"."emp_jobcode" AS "emp_jobcode", "RHS"."emp_hiredate" AS "emp_hiredate", "RHS"."emp_dob" AS "emp_dob" FROM "class" AS "LHS" INNER JOIN "employee" AS "RHS" ON ("LHS"."prof_num" = "RHS"."emp_num"))) WHERE ("crs_code" = 'ACCT-211') ORDER BY emp_fname, "emp_fname" NULLS LAST, "emp_dob" NULLS LAST;

